import{_ as r,o,c as e,a4 as a}from"./chunks/framework.BBs01uty.js";const c=JSON.parse('{"title":"简历 v4 · 前端版","description":"","frontmatter":{"title":"简历 v4 · 前端版"},"headers":[],"relativePath":"resume/v4-frontend.md","filePath":"resume/v4-frontend.md"}'),n={name:"resume/v4-frontend.md"};function s(i,t,l,g,u,p){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="陈俊" tabindex="-1">陈俊 <a class="header-anchor" href="#陈俊" aria-label="Permalink to &quot;陈俊&quot;">​</a></h1><p><strong>求职意向：资深前端开发工程师（React / Vue 方向）</strong></p><p><a href="mailto:641104000@qq.com" target="_blank" rel="noreferrer">641104000@qq.com</a> ｜ 18873579224 技术知识库：<a href="https://jun2333.github.io/knowledge/" target="_blank" rel="noreferrer">https://jun2333.github.io/knowledge/</a> ｜ 随时到岗</p><p>男 ｜ 中国地质大学（本科统招 · 211）｜ 10 年前端开发经验</p><hr><h2 id="核心优势" tabindex="-1">核心优势 <a class="header-anchor" href="#核心优势" aria-label="Permalink to &quot;核心优势&quot;">​</a></h2><ul><li><strong>10 年前端经验</strong>：经历 jQuery → Vue → React 完整技术演进，对 React Fiber 架构、Vue 响应式原理有源码级理解</li><li><strong>架构与工程化</strong>：主导 5+ 子应用微前端（Qiankun）落地；参与多租户 SaaS 平台 <strong>Schema 驱动架构</strong>重构；熟悉 Vite / Webpack 优化、Monorepo、CI/CD 与 Docker 部署</li><li><strong>全栈与 AI 实践</strong>：具备 Node.js（Koa / Nest）服务端能力与 Java（Spring Boot）实践基础；独立完成 RAG 知识库问答系统与 AI 开发工作流框架，具备 Agent 编排与 AI 工程化落地能力</li></ul><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><ul><li><strong>前端核心</strong>：JavaScript / TypeScript（闭包、原型链、事件循环）· React（Fiber、Hooks）· Vue 2/3（响应式原理）</li><li><strong>工程化与架构</strong>：Vite / Webpack · Monorepo · CI/CD · 微前端（Qiankun）· Schema 驱动架构 · BFF · SSR / SSG</li><li><strong>服务端</strong>：Node.js（Koa / Nest）· MySQL / Redis · Docker / Nginx · Java（Spring Boot / MyBatis · 学习实践）</li><li><strong>AI 工程</strong>：RAG（向量检索 + LLM）· Agent 工具调用 · SSE 流式渲染 · AI 辅助开发工作流设计</li></ul><h2 id="工作履历" tabindex="-1">工作履历 <a class="header-anchor" href="#工作履历" aria-label="Permalink to &quot;工作履历&quot;">​</a></h2><p><strong>蜜獾信息技术有限公司</strong> ｜ 高级前端开发工程师 ｜ 2025.03 ~ 2026.06</p><p><strong>2026.06 ~ 至今</strong> ｜ AI 应用实践与技术深耕（自主）</p><ul><li>独立搭建本地化 RAG 知识库问答系统与 AI 开发工作流框架（详见&quot;个人项目&quot;）</li></ul><p><strong>众安在线财产保险股份有限公司</strong> ｜ 资深前端开发工程师 ｜ 2021.03 ~ 2024.09</p><p><strong>移卡科技有限公司</strong> ｜ 高级前端开发工程师 ｜ 2020.05 ~ 2021.01</p><p><strong>深圳技威时代科技有限公司</strong> ｜ 前端开发工程师 ｜ 2017.03 ~ 2020.03</p><h2 id="项目经历" tabindex="-1">项目经历 <a class="header-anchor" href="#项目经历" aria-label="Permalink to &quot;项目经历&quot;">​</a></h2><h3 id="自研模板编辑器-蜜獾-2025-03-2026-06" tabindex="-1">自研模板编辑器（蜜獾）｜ 2025.03 ~ 2026.06 <a class="header-anchor" href="#自研模板编辑器-蜜獾-2025-03-2026-06" aria-label="Permalink to &quot;自研模板编辑器（蜜獾）｜ 2025.03 ~ 2026.06&quot;">​</a></h3><p><strong>背景</strong>：公司邮件 / PDF 模板此前依赖 Word + PDF 编辑器人工维护，单份模板维护需 2 小时以上。</p><p><strong>方案</strong>：自研可视化模板编辑器（TS + React + Vite），支持在富文本环境中插入 FreeMarker 变量与条件块、HTML 自适应布局、在线填变量预览；内部采用 Command 设计模式统一封装操作，实现可扩展与撤销 / 重做。</p><p><strong>成果</strong>：</p><ul><li>单份模板维护成本从 <strong>2 小时降至分钟级</strong>，从&quot;每次改数据都要调模板&quot;变为&quot;仅需一次初始化&quot;</li><li>模板生产能力下放给业务人员，实现自助化生产</li><li>结合 AI 辅助开发流程推进攻坚，交付周期缩短 50%+</li></ul><p><strong>角色</strong>：项目主导者，负责方案设计与核心功能攻坚</p><h3 id="金融-saas-平台全链路重构-·-v5-5-蜜獾-2025-03-2026-06" tabindex="-1">金融 SaaS 平台全链路重构 · v5.5（蜜獾）｜ 2025.03 ~ 2026.06 <a class="header-anchor" href="#金融-saas-平台全链路重构-·-v5-5-蜜獾-2025-03-2026-06" aria-label="Permalink to &quot;金融 SaaS 平台全链路重构 · v5.5（蜜獾）｜ 2025.03 ~ 2026.06&quot;">​</a></h3><p><strong>背景</strong>：多租户金融 SaaS 的旧架构存在两个核心问题：① <strong>巨石代码</strong>——不同租户 / 套餐 / 功能开关导致同一页面有多种表现，if-else 越写越深，新增租户要改几十个文件；② <strong>多版本并行</strong>——旧版本需长期维护，多条 release 分支并行，hotfix 还要跨版本 cherry-pick。</p><p><strong>方案</strong>：参与平台级全链路重构（前端 + 后端 + 配置中心）：</p><ul><li><strong>技术栈迁移</strong>：Vue + JS + Vite → <strong>React + TypeScript + Vite + TanStack Query</strong></li><li><strong>架构升级（Schema 驱动）</strong>：把&quot;变&quot;的部分从代码抽到配置，建立 <code>Context → Rule Engine → Schema → Interpreter</code> 链路，覆盖字段级配置（DFD）/ 业务配置 Schema / UI Schema 三个层面</li><li><strong>组件库重构</strong> + 页面生成方式重构：从手写页面转向配置生成</li></ul><p><strong>成果</strong>：</p><ul><li>代码管理从多版本并行简化为<strong>单版本 + 配置驱动</strong>，不再为每个租户维护独立分支</li><li>新增租户从&quot;改几十个文件&quot;变为<strong>新增一份配置</strong></li><li>配置的灵活性满足多租户诉求，支撑字段级、业务级、UI 级的差异化</li></ul><p><strong>角色</strong>：核心开发，负责前端技术栈迁移与 Schema 架构落地</p><h3 id="forms-gallery-重构-·-v5-4-蜜獾-2025-03-2026-06" tabindex="-1">Forms Gallery 重构 · v5.4（蜜獾）｜ 2025.03 ~ 2026.06 <a class="header-anchor" href="#forms-gallery-重构-·-v5-4-蜜獾-2025-03-2026-06" aria-label="Permalink to &quot;Forms Gallery 重构 · v5.4（蜜獾）｜ 2025.03 ~ 2026.06&quot;">​</a></h3><p><strong>背景</strong>：Forms Gallery 是信贷系统的文档中枢（模板选取 → 变量维护 → 渲染 → 邮件 / 电子签名 / 下载交付）。</p><p><strong>方案与成果</strong>：在 Vue 3 + Vite 技术栈内完成模块重构，优化交互体验并将 FG 抽离为全系统公共模块——能力范围从&quot;仅贷后可用&quot;扩展为<strong>覆盖贷款全生命周期</strong>；与自研模板编辑器打通，实现&quot;编辑 → 预览 → 生产渲染&quot;全链路。</p><p><strong>角色</strong>：负责 FG 模块技术方案设计与核心开发</p><h3 id="客服平台-众安-2021-03-2024-09" tabindex="-1">客服平台（众安）｜ 2021.03 ~ 2024.09 <a class="header-anchor" href="#客服平台-众安-2021-03-2024-09" aria-label="Permalink to &quot;客服平台（众安）｜ 2021.03 ~ 2024.09&quot;">​</a></h3><p><strong>背景</strong>：面向全公司客服场景的通用解决方案（ARK 工作台、IM 在线客服、知识库配置、质量管理、后台管理、业务操作中台 BBC）。</p><p><strong>方案</strong>：React + Antd + Qiankun 微前端 + WebSocket，ARK 作为主应用集成各子应用。</p><p><strong>成果</strong>：</p><ul><li>主导微前端架构设计与落地，完成 <strong>5+ 子应用平稳集成</strong>，实现多团队独立开发与部署，解决协作耦合</li><li>统一入口与 UI 风格；抽取公共组件库 + 搭建项目生成器统一规范；建设在线开发文档体系</li><li>从 0 到 1 搭建业务操作中台（3 人团队），项目<strong>连续两年获集团评比奖项</strong></li></ul><p><strong>角色</strong>：客服中台前端 Leader，负责架构设计、团队管理与跨团队协调</p><h3 id="金融投资-app-hybrid-众安-2021-03-2024-09" tabindex="-1">金融投资 App（Hybrid）（众安）｜ 2021.03 ~ 2024.09 <a class="header-anchor" href="#金融投资-app-hybrid-众安-2021-03-2024-09" aria-label="Permalink to &quot;金融投资 App（Hybrid）（众安）｜ 2021.03 ~ 2024.09&quot;">​</a></h3><p><strong>方案与成果</strong>：H5 端 React + TypeScript + Webpack（MPA + CSR），官网端 Next.js（SSG / ISR）；负责 H5 核心页面开发与性能优化，<strong>首屏 LCP 优化至 1.3s</strong>；参与 Hybrid 通信方案设计，优化 H5 与 Native 交互体验；主导 Next.js 官网静态站点建设。</p><p><strong>角色</strong>：前端组副组长，负责需求评审、方案设计与核心开发</p><h2 id="个人项目-ai-应用实践" tabindex="-1">个人项目（AI 应用实践） <a class="header-anchor" href="#个人项目-ai-应用实践" aria-label="Permalink to &quot;个人项目（AI 应用实践）&quot;">​</a></h2><p><strong>RAG 知识库问答系统</strong>（2026 ｜ <a href="https://github.com/jun2333/knowledge" target="_blank" rel="noreferrer">github.com/jun2333/knowledge</a>）：Koa + TypeScript + Ollama（qwen3:8b / bge-m3）+ Chroma + LangChain + SSE，完全本地运行、零 API 成本。</p><ul><li><strong>问答链路</strong>：文档语义切分 → 向量化入库 → 相似度检索 → LLM 生成，并升级为 Agent 工具调用循环（检索 / 取全文），支持多轮追问与来源引用</li><li><strong>检索评估</strong>：自建 250 题分层回归测试集 + 阈值门禁与基线对比，量化驱动检索优化（Hit@5 98% / Hit@1 88%），并沉淀&quot;负结果&quot;复盘</li><li><strong>批注协作</strong>：把文档批注做成&quot;与 AI 的沟通接口&quot;——AI 产出内容后，对存疑处直接批注、提交给 AI 迭代打磨</li><li><strong>基座化</strong>：将知识库基座与个人内容解耦（索引范围 / 评估集可配置），目标是让任何人都能快速搭建自己的知识库</li></ul><p><strong>DevAgent Harness · AI 开发工作流工具箱</strong>（2026 ｜ <a href="https://github.com/jun2333/dev-agent-harness" target="_blank" rel="noreferrer">github.com/jun2333/dev-agent-harness</a>）：约束 AI 辅助开发流程的通用框架，核心理念为&quot;流程约束 + 精准上下文 + 阶段产出 + 经验闭环&quot;。含 6 种内置工作流、阶段 gate 门禁、两层架构（通用层 + 项目层，git submodule 嵌入）、经验自动沉淀——把 AI 开发从&quot;随机对话&quot;变为可复现的工程流程。</p><p><strong>Agent CLI · 终端 AI 编程助手</strong>（2026 ｜ <a href="https://github.com/jun2333/agent-cli" target="_blank" rel="noreferrer">github.com/jun2333/agent-cli</a>）：从 0 实现命令行 Agent，跑通流式解析 + tool_calls 增量累积、可扩展工具系统、会话管理、TUI 渲染，配单元 + 终端模拟 e2e 测试。</p><h2 id="其他项目" tabindex="-1">其他项目 <a class="header-anchor" href="#其他项目" aria-label="Permalink to &quot;其他项目&quot;">​</a></h2><ul><li><strong>移动端增值业务商城</strong>（技威时代 ｜ 2017 ~ 2020）：jQuery + art-template + SCSS 的 H5 商城，多轮迭代优化体验与运营策略，<strong>一年内用户量增长近 1000 万，累计创造收益超 1000 万</strong></li><li><strong>乐商圈小程序</strong>（移卡）· <strong>运营管理系统</strong>（技威时代）：分别基于 uni-app + Vue 的消费权益小程序、Vue + Webpack + iView 的后台管理系统，负责核心开发与工具化建设</li></ul><h2 id="教育经历" tabindex="-1">教育经历 <a class="header-anchor" href="#教育经历" aria-label="Permalink to &quot;教育经历&quot;">​</a></h2><p><strong>中国地质大学（武汉）</strong> ｜ 信息安全 ｜ 本科（统招 · 211）｜ 2012.09 ~ 2016.06</p>',52)])])}const d=r(n,[["render",s]]);export{c as __pageData,d as default};
